{
  "$schema": "https://docs.renovatebot.com/renovate-schema.json",
  "extends": [
    "config:recommended",
    "group:allNonMajor",
    "group:recommended",
    "group:monorepos",
    "schedule:weekly"
  ],
  "mode": "full",
  "automerge": true,
  "packageRules": [
    {
      "description": "Disable Renovate's built-in github-actions manager — gx owns workflow and composite-action files",
      "matchManagers": ["github-actions"],
      "enabled": false
    },
    {
      "description": "Schedule gx.toml-driven action major upgrades on the first day of the month",
      "matchFileNames": [".github/gx.toml"],
      "groupName": "github-actions",
      "schedule": ["* 0-3 1 * *"]
    },
    {
      "description": "Default apt suites: one registryUrl per stanza of debian:13-slim's own sources (trixie, trixie-updates, trixie-security; main only). The deb datasource merges releases across them, so Renovate's candidate is the one apt would install. Update these together with the base image in android.Dockerfile — a Debian release bump makes them stale.",
      "matchDatasources": ["deb"],
